INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5197122254669352', 'AUBL亚洲大学生篮球联赛', '7907625940', '2025年08月07日 21:39', '【AUBL球队巡礼】西北王出征亚洲赛场对于这支位于「龙城」太原的球队而言，「拼到底」是他们的战斗信条！24次全国八强、18个西北赛区冠军、9名CBA球员、2次全国总冠军...... 数年的赛场拼搏为他们累积了等身荣誉，今年他们则将带着西北王的荣耀，征战亚洲赛场！此次比赛中，太原理工大学与韩国豪强延世大学、以及老对手上海交通大学同处一组，争夺冠军🏆之路势必坎坷，但对太理男篮而言，他们最担心的就是对手不够强大！#AUBL##AUBL亚洲大学生篮球联赛##太原理工大学#', '图片', 0, 0, 0, 'weibo-image-video\\5197122254669352\\1.jpg,weibo-image-video\\5197122254669352\\2.jpg,weibo-image-video\\5197122254669352\\3.jpg,weibo-image-video\\5197122254669352\\4.jpg', '', 'https://weibo.com/7907625940/5197122254669352');
