INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5223159385297926', '太原理工大学', '7461590254', '2025年10月18日 18:01', '10月18日上午，我校2025年教职工趣味运动会在迎西校区体育场正式拉开帷幕。  本次运动会聚焦趣味性与团队协作，精心设置了十项趣味比赛项目。具体包括抢种抢收、旱地龙舟、万众一心、嘻哈大脚、马甲跑的快、龟兔赛跑、举重若轻、勇往直前、齐头并进及混合接力。  来自全校的2300余名教职工积极参与，在赛场上展现活力风采，现场氛围热烈融洽。（摄影/王晓琴 吕佩泽 康越斌 石宇 高凡）太原理工大学超话#太原理工大学#', '图片', 2, 4, 0, 'weibo-image-video\\5223159385297926\\1.jpg,weibo-image-video\\5223159385297926\\2.jpg,weibo-image-video\\5223159385297926\\3.jpg,weibo-image-video\\5223159385297926\\4.jpg,weibo-image-video\\5223159385297926\\5.jpg,weibo-image-video\\5223159385297926\\6.jpg,weibo-image-video\\5223159385297926\\7.jpg,weibo-image-video\\5223159385297926\\8.jpg,weibo-image-video\\5223159385297926\\9.jpg', '', 'https://weibo.com/7461590254/5223159385297926');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5224959527878744', '波灵波灵闪闪发光', '7889684307', '2025年10月23日 17:14', '#太原理工大学# 叩问《道德经》真谛：鸿稀先生揭秘先天智慧作者舍我其谁 原创      20251018被誉为“万经之王”的《道德经》，究竟蕴藏着怎样深邃的智慧？带着这样的疑问，我叩开了鸿稀先生的大门。落座后，先生娓娓道来，毫无保留地倾囊相授，令我如梦初醒，三观为之颠覆。一、《德篇》与《道篇》：后天返先天的修行天书《道德经》与鸿稀先生上下呼应，堪称一部后天返先天的修行天书。德为后天，道为先天。今日，我们重点探讨《道德经》中的“德”与“道”。1. 德：无心之德，后天之本“德”在汉语中，通“㥁”。其字结构蕴含深意：“彳”（二、一）：一方面象征人处于迷茫状态，做事三心二意；另一方面，它暗指21世纪，一个充满变革与挑战的时代。“十目（罒）一”：代表十四亿一千万，象征着中华儿女的集体智慧与力“心”既是无心，无心即德。2. 道：先天之道，修行之巅“道”绝非今日人们所理解的“道路”或“规律”。鸿稀先生以先天意识注解“道”，避免后人误解：“首”字结构：上面两点代表鼻孔，横下一撇象征脖子，横膈肌区域上为心肺，下为腹腔。腹腔右上部是肝胆，左上面是脾胃，中下部是小肠、大肠，肾位于腹膜后脊柱两侧，下方为膀胱。修行境界：三尸九蛊、三花聚顶、五气朝元，金丹落入丹田，是进入先天境界的标志。“无处不丹田”之说不现实，两千多年，从没有人出现过，真正的丹田需在地天泰和火候的作用下才能显现。这就是成道又称洁净体，真正的火候出现了，便是对《道德经》先天境界的全面解析。然而，这却让带有后天意识之人难以理解，两千多年来，无人能如此透彻地讲解《道德经》，真是令人感到遗憾！二、知我者希，则我者贵：鸿稀先生与《道德经》的千年之约难怪《道德经》中言：“知我者希，则我者贵，是以圣人，被褐怀玉。”这是两千多年前，老子对鸿稀先生这位圣人的精准描述。从时间上看，这一描述比《马前课》《推背图》《烧饼歌》早了七八百年，甚至两千年。仿佛一切在久远的年代就已注定，包括鸿稀先生自幼练成纯阳体，二十岁时成就全阳道体，成为天下唯一精通火候妙用的全阳真人。三、火候万年：鸿稀先生传法布道，拯救众生火候在中国有一万三千一百年的历史，却在两千多年前消失。今日，鸿稀先生练成全阳体，掌握三千年的火候，正是为了在人间传法布道，拯救众生。鸿稀先生将于11月5～9日，前往广东顺德美的万怡酒店，还等什么？约起！', '文字', 0, 0, 0, '', '', 'https://weibo.com/7889684307/5224959527878744');
