INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5261964387551121', '太原理工大学', '7461590254', '02月02日 19:58', '20 年不屈，双脚敲出科研路！ #28岁无臂博士论文被Nature旗下期刊录用# #无臂博士用脚敲出4篇SCI论文# #太原理工大学# 太原理工大学超话                \n                                    【折翼二十载！#28岁无臂博士论文被Nature旗下期刊录用#】#无臂博士用脚敲出4篇SCI论文#近日，@太原理工大学 2023级数学学院博士生王海港以第一作者身份撰写的研究论文，被《自然》旗下系列期刊《通讯—物理》录用。这篇论文是王海港用时两年半，凭借双脚“书写”而成。20年前，一场意外夺走了王海港的双臂，但是他始终没有放弃求学。硕博期间，王海港以第一作者身份发表了四篇SCI论文。对于2027年毕业后的规划，他目标明确：继续从事量子信息研究。加油！（人民网山西频道）O网页链接 L人民网的微博视频', '视频', 0, 1, 0, '', 'weibo-image-video\\5261964387551121\\video.mp4', 'https://weibo.com/7461590254/5261964387551121');
