INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5269575432151637', '乖乖小猴666', '7271514552', '02月23日 20:02', '26考研成绩马上出啦，我们一起等花开✨倒计时开始🕐26考研初试成绩马上陆续公布，相信大家的努力不会被辜负，你们都是最棒的准研究生！太原理工大学马克思主义理论自用复试资料已准备好，需要的小伙伴滴滴我哦。祝大家马到成功，金榜题名💯考研超话#马理论##太原理工大学##太原理工大学马克思主义理论#', '文字', 0, 0, 0, '', '', 'https://weibo.com/7271514552/5269575432151637');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5271598116637120', '以你为名61102', '6600089281', '03月01日 09:59', '《乡土中国》是费孝通先生于20世纪40年代后期在西南联大和云南大学讲授“乡村社会学”课程时的讲稿结集，是中国社会学的奠基性著作之一。它并非对中国乡村社会的具体调查报告，而是从宏观视角提炼出中国传统社会的本质特征——“乡土性”。书中提出的“差序格局”“礼治秩序”“无讼”“长老统治”等核心概念，深刻剖析了中国社会结构、伦理观念和文化心理的深层逻辑，为理解中国社会提供了一把关键钥匙。#中国传统文化##传统与当代融合让新疆舞走向世界##中国文化##生活心理学##太原理工大学#  在寒假重读《乡土中国》，我对“中国社会的本质是乡土的”这一论断有了更为深刻的体悟。费孝通先生以其深厚的学养和敏锐的洞察力，将我们习以为常的社会现象，升华为具有普遍解释力的理论。 书中“差序格局”的概念，让我对中国人的人际关系有了全新的认知。与西方社会的“团体格局”不同，中国社会的人际关系如同投入水中的石子所激起的波纹，以“己”为中心，按照亲疏远近向外层层推展。这种格局深刻地影响了我们的道德观念、法律意识和行为方式，使得“人情”“关系”成为社会运行的重要润滑剂。 “礼治秩序”与“法治秩序”的对比，则引发了我对传统与现代关系的深入思考。在乡土社会中，人们依靠传统的“礼”来维持秩序，这种“礼”是经过长期实践检验、被全体成员共同认可的行为规范。而现代社会则强调“法治”，依靠明确的法律条文来界定权利与义务。在当代中国，这两种秩序并非完全对立，而是在不断地碰撞、融合，共同塑造着我们的社会生活。 此外，书中对“乡土本色”的描绘，也让我重新审视了自己的成长环境。无论是春节时阖家团圆的“家”的观念，还是邻里之间守望相助的温情，都深深植根于乡土文化的土壤。这种文化基因，即使在高度城市化的今天，依然深刻地影响着我们的价值判断和生活方式。', '文字', 0, 0, 0, '', '', 'https://weibo.com/6600089281/5271598116637120');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5271600011156361', '以你为名61102', '6600089281', '03月01日 10:07', '#好书推荐##文化自信##太原理工大学##乡土中国# ​', '图片', 0, 0, 0, 'weibo-image-video\\5271600011156361\\1.jpg,weibo-image-video\\5271600011156361\\2.jpg', '', 'https://weibo.com/6600089281/5271600011156361');
