INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5273145556864439', '是幼儿园高材生', '7330177758', '03月05日 16:28', '📢太原高校的宝子注意！三环集团26届春招来啦🔥（附内推码）太原的准毕业生们看过来！三环集团2026届春招正式发车啦！🚎不管你是太理、山大、太科还是中北的同学，通通都可以投递！岗位多多，上岸机会超大！🎉💡 【划重点！秋招遗憾党福音】秋招面试挂了？投递石沉大海没反应？👉 不要慌！春招统统可以再次投递！ 相当于多一次满血复活拿Offer的机会，千万别错过！⏰ 【线下宣讲会信息——就在太理！】想和HR面对面交流，直接了解一手的宝子直接来现场：📍 地点： 太原理工大学（迎西校区）公共阶梯教室4📅 时间： 2026年3月12日 14：30💰 【薪资待遇真的香（重点看这里👇）】材料/机电等专业简直是天选！本科： 月薪1.2万起（综合年薪16-19万起）硕士： 月薪1.7万~2.0万起（综合年薪最高可达29万起！材料和机电研发类待遇超好！）博士： 综合年薪40万起！（附言：试用期/学习期薪资与正式offer薪资完全一致，不打折！以上还不包括月度绩效、年终奖和岗位津贴哦！）🏢 【工作地点神仙打架】广东（潮州/深圳）、四川（成都/德阳/南充）、江苏苏州，想去南方发展或者回川渝的宝子闭眼冲！🎁 【福利拉满，打工人狂喜】不仅给钱痛快，还包揽你的衣食住行！提供人才公寓 🏠 + 自助餐厅（有伙食补贴）🍲 + 团建中心/健身房 🏋️‍♂️，下班直接开启度假模式！🚀 【投递方式看这里】 1️^ PC端网申地址： 2️⃣ 投递时一定要填内推码：815797 ！！（填写内推码，简历会被优先筛选跟进哦，冲冲冲！）hr.cctc.cc有任何关于岗位的疑问，欢迎在评论区问我，大使随时为你解答！冲就完事了！💪#太原理工大学 #三环集团 #春招 # 山西大学 #中北大学 #研究生 #太原科技大学', '图片', 0, 0, 0, 'weibo-image-video\\5273145556864439\\1.jpg,weibo-image-video\\5273145556864439\\2.jpg', '', 'https://weibo.com/7330177758/5273145556864439');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5279944707934032', '洁净煤技术杂志', '3630397290', '03月24日 10:46', '#太原理工大学# 金燕教授团队，建立350 MW超临界CFB“活性残碳-活性石灰石”双存量动态模型，耦合CPFD气固流动计算，揭示周期性压火启动7个阶段中残碳与石灰石存量瞬态演化规律：停炉密闭阶段残碳0 kg、石灰石0 kg，热态启动后30 min内残碳快速回升至6353 kg、石灰石恢复至2375 kg，脱硫效率由0反弹至62%，为深调峰灵活控制提供量化边界。相关研究成果以《350 MW超临界CFB锅炉压火启动过程活性存量动态特性》 为题发表在《洁净煤技术》。 #超临界循环流化锅炉#  O350 MW超临界CFB锅炉压火启动过程活性存量动态特性', '文字', 0, 0, 0, '', '', 'https://weibo.com/3630397290/5279944707934032');
