INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5286265269522223', '小哥体育', '3224935541', '04月10日 21:21', '太理进攻就是传球艺术！每一次穿针引线，每一次恰到好处的分球，都在诠释团队篮球的最高境界。不看人、声东击西、击地直塞——太原理工的进攻，比艺术更流畅。#太原理工大学##cubal西北赛区##传球艺术##这一刻胜一切# L小哥评篮球的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5286265269522223\\video.mp4', 'https://weibo.com/3224935541/5286265269522223');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5288416670385541', '太原理工大学', '7461590254', '04月16日 19:50', '用色环，打开太原理工大学把百年风华揉进色彩里每一抹，都是太理人刻在心底的记忆拍摄：周敬轩 陈逸飞  剪辑：卢娅彤 #我有我的春天#太原理工大学超话#太原理工大学# L太原理工大学的微博视频 ​', '视频', 1, 0, 0, '', 'weibo-image-video\\5288416670385541\\video.mp4', 'https://weibo.com/7461590254/5288416670385541');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5291357222474052', '太原理工大学', '7461590254', '04月24日 22:35', '汾河之畔，世纪学府，百廿薪火显峥嵘；  求实创新，青春如火，绿茵赛场见锋芒。  今日我校举办校运会，绿茵场上尽显太理学子精神风貌。  旗帜飘扬处，是永不言败的信仰；赛道延伸间，是超越自我的誓言。  让我们以运动之名，致敬百廿学府的厚重积淀；以拼搏之志，拥抱新时代的壮阔征程！太原理工大学超话#太原理工大学#', '图片', 1, 5, 0, 'weibo-image-video\\5291357222474052\\1.jpg,weibo-image-video\\5291357222474052\\2.jpg,weibo-image-video\\5291357222474052\\3.jpg,weibo-image-video\\5291357222474052\\4.jpg,weibo-image-video\\5291357222474052\\5.jpg,weibo-image-video\\5291357222474052\\6.jpg,weibo-image-video\\5291357222474052\\7.jpg,weibo-image-video\\5291357222474052\\8.jpg,weibo-image-video\\5291357222474052\\9.jpg', '', 'https://weibo.com/7461590254/5291357222474052');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5291360576866921', '太原理工大学', '7461590254', '04月24日 22:48', '春风化雨，希望在即，奋斗篇章汗水铸；桃李芬芳，憧憬未来，梦想距离脚步量。看！新时代的太理人正以昂扬之姿，迈向教育强国的星辰大海！#太原理工大学#太原理工大学超话 ​', '图片', 0, 2, 0, 'weibo-image-video\\5291360576866921\\1.jpg,weibo-image-video\\5291360576866921\\2.jpg,weibo-image-video\\5291360576866921\\3.jpg,weibo-image-video\\5291360576866921\\4.jpg,weibo-image-video\\5291360576866921\\5.jpg,weibo-image-video\\5291360576866921\\6.jpg,weibo-image-video\\5291360576866921\\7.jpg,weibo-image-video\\5291360576866921\\8.jpg,weibo-image-video\\5291360576866921\\9.jpg', '', 'https://weibo.com/7461590254/5291360576866921');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5291361557546280', '太原理工大学', '7461590254', '04月24日 22:52', '体育是力量的角逐；体育是智慧的较量；在运动会上，我们将不断挑战自己、挑战极限，用我们的行动去追求更高、更快、更强！#太原理工大学#太原理工大学超话 ​', '图片', 0, 0, 0, 'weibo-image-video\\5291361557546280\\1.jpg,weibo-image-video\\5291361557546280\\2.jpg,weibo-image-video\\5291361557546280\\3.jpg,weibo-image-video\\5291361557546280\\4.jpg,weibo-image-video\\5291361557546280\\5.jpg,weibo-image-video\\5291361557546280\\6.jpg,weibo-image-video\\5291361557546280\\7.jpg,weibo-image-video\\5291361557546280\\8.jpg,weibo-image-video\\5291361557546280\\9.jpg', '', 'https://weibo.com/7461590254/5291361557546280');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5291648810483828', '太原理工大学', '7461590254', '04月25日 17:54', '以汗水为墨，绘青春画卷；以奔跑为诗，写热血篇章。太原理工大学 2026 年学生田径运动会开幕。#太原理工大学#太原理工大学超话 L太原理工大学的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5291648810483828\\video.mp4', 'https://weibo.com/7461590254/5291648810483828');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5292022510390155', '太原理工大学', '7461590254', '04月26日 18:39', '悦动太理·健体育魄 | 2026年太原理工大学首届师生环跑太原理工大学超话#太原理工大学# L太原理工大学的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5292022510390155\\video.mp4', 'https://weibo.com/7461590254/5292022510390155');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5292024599152803', '太原理工大学', '7461590254', '04月26日 18:47', '跑道上追风的身影，阳光下扬起的笑脸，是青春最美的模样。太原理工大学运动会采访已送达~#太原理工大学#太原理工大学超话 L太原理工大学的微博视频 ​', '视频', 2, 2, 0, '', 'weibo-image-video\\5292024599152803\\video.mp4', 'https://weibo.com/7461590254/5292024599152803');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5292730843661725', '太原理工大学', '7461590254', '04月28日 17:33', '春和景明，万象更新太原理工大学 2026 年老年人健步周正式启动！银发映初心，健步向未来老同志们精神矍铄、步履铿锵一路欢声笑语，尽展昂扬风采致敬太原理工奠基人！他们曾为学校耕耘奉献是学校发展的宝贵财富如今依旧心系母校、聚力同行启航新征程，聚力新发展以运动强体魄，以初心助发展太理始终用心用情做好服务让银发余热生辉，与母校共赴新程！#太原理工大学 ##我的学校名片#太原理工大学超话 @中国大学生在线 @中青校媒 L太原理工大学的微博视频', '视频', 1, 1, 0, '', 'weibo-image-video\\5292730843661725\\video.mp4', 'https://weibo.com/7461590254/5292730843661725');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5292731204374157', '太原理工大学', '7461590254', '04月28日 17:35', '百廿学府，薪火赓续山河万里，情系太理。秩年校友重返太理工，重走求学路，共忆青春岁月；相聚话往昔，共叙韶华芳华；聚力谋新篇，共绘发展蓝图。迎西底蕴沉淀，明向风华正茂，虎峪岁月绵长，每一隅都是独属于太理人的独家记忆。一朝入太理，一生太理人。跨越山海奔赴而归，以校友之力赋能母校，以赤子之心守望故土，初心不改，携手同行，同心奔赴太原理工崭新征程✨#太原理工大学 ##太理秩年返校 ##情系太理共叙芳华 ##百年学府 ##校友归来#@中国大学生在线 @中青校媒太原理工大学超话#太原理工大学# L太原理工大学的微博视频', '视频', 0, 0, 0, '', 'weibo-image-video\\5292731204374157\\video.mp4', 'https://weibo.com/7461590254/5292731204374157');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5292731766148413', '太原理工大学', '7461590254', '04月28日 17:37', '青春燃动太理，运动不负韶华奔跑追风，逐梦前行；热血赛场，活力满格。2026 年学生田径运动会圆满收官，首届师生环校跑热力启航。赛道之上，少年奋勇拼搏、驰骋争先；环校途中，师生并肩同行、步履向阳。每一次冲刺、每一次奔跑，都是青春最美的模样。以运动强体魄，以奋斗致青春。（剪辑：褚天珩）#太原理工大学 #太原理工大学超话#校运会##师生环校跑 ##青春正好 ##运动不负热爱#  @中国大学生在线 @中青校媒 L太原理工大学的微博视频', '视频', 0, 0, 0, '', 'weibo-image-video\\5292731766148413\\video.mp4', 'https://weibo.com/7461590254/5292731766148413');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5292979159566882', '太原理工大学', '7461590254', '04月29日 10:00', '太原理工大学原创美育项目《三晋民俗韵律操》以体传文  以美育人承非遗文脉 展青春风采#校运会 ##三晋民俗韵律操 ##美育非遗##我的学校名片#@中国大学生在线 @中青校媒太原理工大学超话#太原理工大学# L太原理工大学的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5292979159566882\\video.mp4', 'https://weibo.com/7461590254/5292979159566882');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5294851834777174', '用户7517628025', '7517628025', '05月04日 14:01', '太原理工大学超话 出太理801初试＋复试资料，#信号与系统##数电##太原理工大学##通信工程##新一代电子信息# ​', '文字', 0, 1, 0, '', '', 'https://weibo.com/7517628025/5294851834777174');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5294981255272953', 'LightScienceApplications', '3730060912', '05月04日 22:36', '【Light·封面 | 大范围高精度分布式温度监测】近日，来自太原理工大学的李健教授和张明江教授团队在《Light: Science & Applications》上发表论文，围绕拉曼光时域反射分布式光纤传感系统中传感距离、空间分辨率与温度精度难以同时提升的核心瓶颈，提出了一种复数域方波宽度啁啾脉冲压缩的新型拉曼分布式光纤传感方法。该方案通过方波宽度啁啾探测脉冲、复数域匹配滤波和复数域包络提取去噪，实现了数十公里的传感距离、亚米级空间分辨率和亚摄氏度温度精度，为超长距离、高空间分辨率、高精度分布式温度测量提供了新的研究思路和技术路径。【点击链接阅读📖原文：O网页链接】#Light: Science & Applications##太原理工大学##光学##光纤#', '图片', 1, 0, 0, 'weibo-image-video\\5294981255272953\\1.jpg,weibo-image-video\\5294981255272953\\2.jpg,weibo-image-video\\5294981255272953\\3.jpg', '', 'https://weibo.com/3730060912/5294981255272953');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5295278492222036', '萌娃历险记', '6613452442', '05月05日 18:17', '哪所211理工大学更胜一筹？ #华东理工大学# #南京理工大学# #太原理工大学# L萌娃历险记的微博视频 ​', '视频', 0, 1, 0, '', 'weibo-image-video\\5295278492222036\\video.mp4', 'https://weibo.com/6613452442/5295278492222036');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5296259871016334', '太原理工大学', '7461590254', '05月08日 11:16', '那些披星戴月的日夜，那些笔尖不歇的坚持，都将在六月绽放光芒。最后 30 天，愿每一份坚持都不被辜负，每一个梦想都能开花。太原理工已备好星光与晚风，等你奔赴新程！#高考##梦想##太原理工大学#太原理工大学超话 L太原理工大学的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5296259871016334\\video.mp4', 'https://weibo.com/7461590254/5296259871016334');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5299313372826168', '平头GGBond', '7201558090', '05月16日 21:30', '毕业季，路漫漫其修远兮#太原理工大学##毕业季#太原理工大学超话 ​', '图片', 0, 0, 0, 'weibo-image-video\\5299313372826168\\1.jpg,weibo-image-video\\5299313372826168\\2.jpg,weibo-image-video\\5299313372826168\\3.jpg,weibo-image-video\\5299313372826168\\4.jpg,weibo-image-video\\5299313372826168\\5.jpg,weibo-image-video\\5299313372826168\\6.jpg,weibo-image-video\\5299313372826168\\7.jpg,weibo-image-video\\5299313372826168\\8.jpg,weibo-image-video\\5299313372826168\\9.jpg', '', 'https://weibo.com/7201558090/5299313372826168');
