INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5303985541743021', '刀师父爱看球', '7929427818', '05月29日 18:55', '今日#CUBAL全国32强赛#，#太原理工大学# 对阵#北京大学# 的比赛正在进行中。第四节比赛，曹芷豪上篮打进后再中三分砍下23分，太原理工末节领先北大25分。 ​', '图片', 2, 3, 0, 'weibo-image-video\\5303985541743021\\1.jpg', '', 'https://weibo.com/7929427818/5303985541743021');
