INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5309016294557423', '太原理工大学', '7461590254', '06月12日 16:06', '#党课开讲啦# 太原理工大学超话 #太原理工大学#                \n                                    #党课开讲啦#【微党课1：牢记初心使命 坚守立党为公的政治本色】立党为公担使命，实干笃行谱新篇。6月12日16:00，跟随@复旦大学 @井冈山大学 @中国人民大学 @湖南大学 师生党员，走进2026年高校党组织示范微党课第1讲《牢记初心使命 坚守立党为公的政治本色》。点击O网页链接 参与互动，查看更多精彩内容。#我和祖国共成长#  L中国大学生在线的微博视频 2026年高校党组织示范微党课展播 第1讲', '视频', 0, 0, 0, '', 'weibo-image-video\\5309016294557423\\video.mp4', 'https://weibo.com/7461590254/5309016294557423');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5310095837889408', '太原理工大学', '7461590254', '06月15日 15:36', '“日月不失其体，故蔽而复明；江汉不失其源，故穷而复通”，韧性立身，校训为伴，祝所有毕业生鹏程万里！#太原理工大学#太原理工大学超话#我的学校名片 ##毕业典礼 ##毕业寄语 #@中国大学生在线 L太原理工大学的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5310095837889408\\video.mp4', 'https://weibo.com/7461590254/5310095837889408');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5310097595040778', '太原理工大学', '7461590254', '06月15日 15:43', '我校2001届水利水电建筑工程专业本科毕业生、优秀校友代表、中国电建北京勘测设计研究院党委副书记、总经理杨晓辉先生发言#太原理工大学 #太原理工大学超话 @中国大学生在线 工科生的成长从没有捷径，书本知识终究要在实践中落地。初入职场，同学们一定会从基础工作做起，跑现场、查资料、改图纸、跑调研，这些基础工作谁也绕不开，别被琐事困住手脚，但也别小看他们，我自己当年也是这样一步步走过来的。要在日复一日的实干中积累经验、精进技术，摒弃浮躁、耐得住寂寞、守得住初心，把所学理论变成真本事，在解决实际问题中打磨心性，日积月累，定能厚积薄发。 L太原理工大学的微博视频', '视频', 1, 1, 0, '', 'weibo-image-video\\5310097595040778\\video.mp4', 'https://weibo.com/7461590254/5310097595040778');
