INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5312690634886868', '太原理工大学', '7461590254', '06月22日 19:26', '原创歌曲《太理青春》毕业季限定上线明向的钟声飘向远方惊醒了四年，温柔了回想从迎西到明向从开学第一碗刀削面到最后一顿智林食堂那些拼到底的夜、笑到疯的忙都化作这首歌轻轻唱给每一位太原理工的你太理啊太理，毕业快乐（来源：经济与管理学院）#太原理工大学 #太原理工大学超话#毕业季##太理毕业 ##校园原创音乐#@中国大学生在线 @中青校媒 L太原理工大学的微博视频', '视频', 0, 0, 0, '', 'weibo-image-video\\5312690634886868\\video.mp4', 'https://weibo.com/7461590254/5312690634886868');
