INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5315019759944025', '阿才说球', '6892261487', '06月29日 05:42', '杨虎龙14分8板1断5规，太原理工大学男篮淘汰北京大学男篮晋级CUBAL巅峰四强！杨虎龙亲自淘汰了自己的老大哥昂萨尔，期待后续杨虎龙的表现！#太原理工大学##cubal大学生篮球联赛##阿才说球#CBA超话CUBA超话 L阿才说球的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5315019759944025\\video.mp4', 'https://weibo.com/6892261487/5315019759944025');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5315134925048188', '十六分的k陈', '6669307456', '06月29日 13:19', '山西男篮超话太原理工大学赢了北京大学！全国四强 #CUBAL ##太原理工大学# L十六分的k陈的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5315134925048188\\video.mp4', 'https://weibo.com/6669307456/5315134925048188');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5315208639940993', '太原新闻网官方微博', '2346031615', '06月29日 18:12', '#太原# 【太理操场夯爆了！这就是山西篮球的氛围！】#太原理工大学# 6月28日晚，第28届中国大学生篮球联赛(CUBAL)男篮全国八强赛再战一场，太原理工大学男篮主场以79比71击败北京大学队，从而以总比分155比150淘汰对手挺进全国四强。当晚，太原理工大学迎西校区操场架设户外大屏，汇聚千余名师生及篮球爱好者现场观赛，气氛热烈，场面震撼。#cubal大学生篮球联赛# 太报全媒体记者 雷蕾 L太原新闻网官方微博的微博视频', '视频', 0, 0, 0, '', 'weibo-image-video\\5315208639940993\\video.mp4', 'https://weibo.com/2346031615/5315208639940993');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5315218852808555', '非妄想', '7359805691', '06月29日 18:53', '太理就这样狠狠地赢取胜利，淘汰北大，晋级四强，让会读书的回去读书，让会打篮球的太原理工大学成为冠军，太理实力真硬。#太原理工大学# #北大# #CUBAL大学生篮球联赛#                 \n                                    CUBAL｜太理淘汰北大，晋级四强！八强赛次回合，回到主场的太原理工状态正盛，在段成果的带领下早早建立起两位数的领先优势，即使进入下半场后，北大在邓奕豪带领下，掀起数波反击浪潮，但比赛最后时刻，太理稳住局势，未让胜利溜走，惊险收获胜利，队史第16次晋级全国四强。这是北大男篮第三次造访太原理工大学迎西校区体育馆，但他们还未能从这里带走一胜。全国四强赛将于7月11日于秦皇岛开打，太原理工将在半决赛中对阵湖南工业大学。CUBA超话', '图片', 0, 0, 0, 'weibo-image-video\\5315218852808555\\1.jpg,weibo-image-video\\5315218852808555\\2.jpg', '', 'https://weibo.com/7359805691/5315218852808555');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5318366576511747', '山西网络广播电视台', '7730909027', '07月08日 11:21', '中国第16次北冰洋考察启程，太原理工大学三名师生随船再出征#北冰洋考察##太原理工大学# L山西网络广播电视台的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5318366576511747\\video.mp4', 'https://weibo.com/7730909027/5318366576511747');
