INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5319878324258177', '太原理工大学', '7461590254', '07月12日 15:28', '从燃油时代到电动时代，从节能竞技到方程式竞速，十六载匠心沉淀，晋翔车队的每一代队员都在用自己的双手，将图纸上的线条变成驰骋赛场的钢铁猛兽。我们用镜头记录下了这个春天的训练日常——扳手与金属的碰撞声、数据屏幕前的反复推敲、车手与工程师的专注对话。这些画面，是晋翔最真实的模样，也是太原理工大学“求实创新”精神在实践中的缩影。一起走进晋翔车队的2026赛季备战现场！剪辑：陈逸飞拍摄：陈逸飞,褚天珩,彭俊翔,李济成,周敬轩,卢娅彤#太原理工大学#太原理工大学超话 L太原理工大学的微博视频', '视频', 0, 0, 0, '', 'weibo-image-video\\5319878324258177\\video.mp4', 'https://weibo.com/7461590254/5319878324258177');
