INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5319986270963137', '太原理工大学', '7461590254', '07月12日 22:37', '太原理工大学男篮，队史第三座全国总冠军！🏆#CUBAL ##全国总冠军 ##太原理工大学 ##我的学校名片 #@中国大学生在线 @CUBAL大学生篮球联赛 哨声落下的那一刻，是无数个清晨与深夜的回响。从青涩到王者，他们把“太原理工”，第三次刻上了全国之巅。这不是运气，是日复一日的坚持；这不是终点，是一支球队精神的传承。致敬每一位挥洒汗水的少年，太原理工，永远向前！💪陪太理，拼到底！！！ L太原理工大学的微博视频', '视频', 39, 27, 0, '', 'weibo-image-video\\5319986270963137\\video.mp4', 'https://weibo.com/7461590254/5319986270963137');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5319989542258819', '太原理工大学', '7461590254', '07月13日 06:51 转赞人数超过10', '陪太理，拼到底！ #太原理工大学# 太原理工大学超话                \n                                    CUBA超话 #太原理工大学CUBAL冠军# 太理总冠军🏆陪太理！ 拼到底！#太原理工vs清华大学##cubal巅峰四强##cubal# ​', '图片', 0, 3, 0, 'weibo-image-video\\5319989542258819\\1.jpg', '', 'https://weibo.com/7461590254/5319989542258819');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5319993765924968', '躲猫咪的珞珞', '5664046881', '07月12日 23:06', '#太原理工大学CUBAL冠军#啊啊啊啊！十多年前把我“骗进”太理的篮球队，又夺冠了！！！#cubal##太原理工大学# 王洪那批球员之后，蛰伏沉寂了太多年，甚至西北王都丢了几年。陪他们经历过，才知道一路有多艰辛！前年在杭州现场，眼睁睁的看着， 杨子豪末节苦追，输6分，怎么追都追不上。今天在母校，输清华的6分又赢回来了！', '文字', 0, 1, 0, '', '', 'https://weibo.com/5664046881/5319993765924968');
