INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5319995438406122', '山西全体育', '1406511184', '07月13日 08:22 转赞人数超过10', '在今晚刚刚结束的第28届CUBA男篮决赛中，太原理工大学队以71比65力克清华大学队，历史上第三次捧起总冠军奖杯，时隔14年再次登上最高领奖台。曹芷豪凭借23分、3篮板、2次助攻获得MVP。太原理工大学在两个校区设置大屏幕，为在校师生在周边群众提供了一个开心的夜宴。CUBA超话#太原理工大学# ​', '图片', 3, 5, 0, 'weibo-image-video\\5319995438406122\\1.jpg,weibo-image-video\\5319995438406122\\2.jpg,weibo-image-video\\5319995438406122\\3.jpg,weibo-image-video\\5319995438406122\\4.jpg,weibo-image-video\\5319995438406122\\5.jpg,weibo-image-video\\5319995438406122\\6.jpg,weibo-image-video\\5319995438406122\\7.jpg,weibo-image-video\\5319995438406122\\8.jpg,weibo-image-video\\5319995438406122\\9.jpg', '', 'https://weibo.com/1406511184/5319995438406122');
