INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320083019926015', '体育界的趣味挖掘机', '1729793997', '07月13日 05:01', '三分憾负转眼五分制胜，太原理工大学力克北京大学完成复仇，强势闯入CUBA全国四强 #CUBA# #太原理工大学# #北京大学# L体育界的趣味挖掘机的微博视频 ​', '视频', 0, 1, 0, '', 'weibo-image-video\\5320083019926015\\video.mp4', 'https://weibo.com/1729793997/5320083019926015');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320083683410085', '篮球面对面', '6192877183', '07月13日 05:04', '#太原理工大学# 勇夺 #cubal# 总冠军！曹芷豪狂砍23分荣膺MVP，刘少伟贡献17分，陈子文拿下10分，杨子豪斩获9分，杨虎龙添得6分！全员奋起，火力全开！一雪前耻，力克清华！王者归来，巅峰再临！实至名归！ L篮球面对面的微博视频 ​', '视频', 2, 1, 0, '', 'weibo-image-video\\5320083683410085\\video.mp4', 'https://weibo.com/6192877183/5320083683410085');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320134564252570', '_-closer-_', '7511934320', '07月13日 08:26', '这是一场巨大的戒断。很幸福，见证历史。最好的太原理工，永远陪太理拼到底！CUBA超话#cubal大学生篮球联赛##太原理工大学# ​', '图片', 0, 0, 0, 'weibo-image-video\\5320134564252570\\1.jpg,weibo-image-video\\5320134564252570\\2.jpg,weibo-image-video\\5320134564252570\\3.jpg,weibo-image-video\\5320134564252570\\4.jpg,weibo-image-video\\5320134564252570\\5.jpg,weibo-image-video\\5320134564252570\\6.jpg,weibo-image-video\\5320134564252570\\7.jpg,weibo-image-video\\5320134564252570\\8.jpg,weibo-image-video\\5320134564252570\\9.jpg', '', 'https://weibo.com/7511934320/5320134564252570');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320146231231820', 'Osports全体育传媒', '1616066825', '07月13日 09:12', '曹芷豪率太原理工大学夺冠并斩获MVP#CBA##以城之名##CBA选秀##CBA选秀大会##2026CBA选秀###2026CBA选秀大会##曹芷豪##太原理工大学# ​', '图片', 0, 0, 0, 'weibo-image-video\\5320146231231820\\1.jpg,weibo-image-video\\5320146231231820\\2.jpg', '', 'https://weibo.com/1616066825/5320146231231820');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320157590458033', '篮球摄手虎', '1909323013', '07月13日 09:57', '“太原理工vs清华大学总决赛完整版”#篮球##cubal大学生篮球联赛##太原理工大学##清华大学# L篮球摄手虎的微博视频 ​', '视频', 2, 1, 0, '', 'weibo-image-video\\5320157590458033\\video.mp4', 'https://weibo.com/1909323013/5320157590458033');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320177776591526', '初学者更新', '6514181079', '07月13日 11:18', '#太原理工大学# 太原理工，冠军！！！🏆71-65，赢了！我在外地，隔着屏幕看到终场哨响那一刻，眼眶突然就热了。连续两年总决赛遇上清华，去年81-86惜败，今年终于亲手把结局改写了。从2012年到2026年，14年，队史第三冠，“西北王”终于成了全国王！曹芷豪23分加冕FMVP，最后一罚时全场高喊MVP。刘少伟拼到抽筋倒地，杨虎龙抢下致胜进攻篮板——每个人都拼到了极限。先赢北大，再胜清华，这一路荡气回肠。从2010、2012两度登顶，到这么多年蛰伏，太理篮球的血性从来没丢过。作为一个在外面的山西人，看到家乡的球队在全国舞台上捧杯，那种骄傲真的说不完。太理，牛！山西，牛！🔥#cuba#', '文字', 0, 1, 0, '', '', 'https://weibo.com/6514181079/5320177776591526');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320203669867758', '张世尧Shaw', '5388507119', '07月13日 13:01', '有幸见证总冠军💥#cubal巅峰四强##太原理工大学# 2秦皇岛 ​', '图片', 0, 0, 0, 'weibo-image-video\\5320203669867758\\1.jpg', '', 'https://weibo.com/5388507119/5320203669867758');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320205590071047', 'AmbitionGirl_J', '5690134960', '07月13日 13:08', '从大学16.17年开始的王洪 刘佳鑫 周子旭还有消失网络的冯瀚圃到如今十年后这种青春的感觉和回忆还在当时拿到西北王就很开心现在全国总冠军🏆！太燃了！好久没活跃的群也有了消息就像和过去对话一样！人总要有点热爱 生活才不那么无趣夕阳与太理同爱！#太原理工大学# 2太原·太原理工大学迎西校区', '视频', 0, 0, 0, '', 'weibo-image-video\\5320205590071047\\video.mp4', 'https://weibo.com/5690134960/5320205590071047');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320213713129104', '十六分的k陈', '6669307456', '07月13日 13:40', '体育比赛超话第三次！太原理工男篮加冕全国总冠军 #太原理工大学 #CUBAL #篮球 #体育 #大学生 L十六分的k陈的微博视频 ​', '视频', 0, 0, 0, '', 'weibo-image-video\\5320213713129104\\video.mp4', 'https://weibo.com/6669307456/5320213713129104');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320215756802230', '苏嫀', '2967497513', '07月13日 13:49', '关注cuba从“东霆西圃南豹北凯”那个时代开始，而现在时隔多年已经成为了一种情怀。2016年洪队与冯翰圃在决赛现场泪洒赛场，回校后任院长激情演讲 “我们一定要战胜清华大学 为太原理工大学争光” ……这一等就是十年。这十年是几代太理男篮的拼搏，从洪队、冯翰圃、徐杰、王思奇、孙畅，到五小、刘佳鑫，再到杜智博、曹芷豪、杨子豪……是太理精神一代又一代的传承。2024年，机长杜智博一记三分绝杀一战成名，24分主场逆转北大，而之后决赛惜败清华。从2016年到2026年，用了整整十年的时间弥补了他们遗憾 ， 这一年我们终于做到了 永远不要低估一颗总冠军的心！#cubal大学生篮球联赛##太原理工大学#', '图片', 0, 0, 0, 'weibo-image-video\\5320215756802230\\1.jpg,weibo-image-video\\5320215756802230\\2.jpg,weibo-image-video\\5320215756802230\\3.jpg', '', 'https://weibo.com/2967497513/5320215756802230');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320291909371798', '小布和小聿', '1633244612', '07月13日 18:51', '是的，太原理工大学，2026CUBAL总冠军这是每个夏天，专属于太原理工篮球迷的狂欢夜。昨晚，太原理工大学赢下了CUBAL全国大学生篮球联赛总冠军。真的做到了。全员的默契，在赛场上流淌得淋漓尽致。段成果，稳。节奏不乱，呼吸不抖，是刻在骨子里的本能。刘少伟，硬。每一个篮板都是卡住位置、顶开对手拼下来的。他的硬，不是莽撞，是精确——起跳时机、落地重心、二次进攻的衔接，全部算过。曹芷豪，狂。从开场第一秒就亮出锋芒。三分线外的出手果断到让人来不及紧张。总决赛MVP，他值得。陈子文，锐。焦灼时刻，他投进那记三分，像往沸腾的油锅里泼进一瓢冷水——全场炸了，他自己面无表情地退防。贴防对方持球人时，双脚碎步密得像缝纫机针脚，快，且能抢。每一个球都去扑。杨虎龙，沉。那个制胜的进攻篮板，起跳之前已经预判了球的落点，卡位时双脚像钉进地板。拿下篮板那一刻，他不急着补篮，稳稳护住，等队友落位——这份冷静，比篮板本身更珍贵。孟凡森，准。他的投篮，接球、屈膝、起跳、拨腕，整套动作像上了发条。……还有很多球员很棒，等我这个新球迷再理理多看看比赛～第三座全国总冠军奖杯。第三冠，献给太原理工124周年。迎西校区和明向校区的操场上，挤满了守在大屏前的人。屏幕上的每一次攻防转换，都牵动着几千人的呼吸。人多，却不乱，气氛极好。又想起之前听到的那句话：这里的人们似乎深爱他们的球队。不，不是“似乎”。是确认。这支队伍的专业，不在纸面上，在细节里。防守轮转快一步，挡拆角度刁一度，快攻的推进像精密齿轮咬合。每一套战术的跑位、每一次边线球的布置，都经过千百次打磨。场上五人之间几乎不用眼神，就知道下一步往哪走——那是训练场上日复一日磨出来的默契。校区大屏前，散场时人群没有一哄而散。有人静静坐着，有人成堆低声复盘，仿佛还在消化刚才的一切。没有人催他们。这夜，再长一点也没关系。（图为上次6.28太理主场现场）#cubal##太原理工大学##太原理工大学夺cubal总冠军##陪太理拼到底#', '图片', 0, 0, 0, 'weibo-image-video\\5320291909371798\\1.jpg,weibo-image-video\\5320291909371798\\2.jpg,weibo-image-video\\5320291909371798\\3.jpg,weibo-image-video\\5320291909371798\\4.jpg,weibo-image-video\\5320291909371798\\5.jpg,weibo-image-video\\5320291909371798\\6.jpg,weibo-image-video\\5320291909371798\\7.jpg,weibo-image-video\\5320291909371798\\8.jpg', '', 'https://weibo.com/1633244612/5320291909371798');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5320345492134524', '山西全体育', '1406511184', '07月13日 22:24', '这是太原理工大学男篮当年夺冠的几张照片。十几年过去了，物是人非，一转眼都老了，都是回忆了。#太原理工大学# ​', '图片', 0, 11, 0, 'weibo-image-video\\5320345492134524\\1.jpg,weibo-image-video\\5320345492134524\\2.jpg,weibo-image-video\\5320345492134524\\3.jpg,weibo-image-video\\5320345492134524\\4.jpg,weibo-image-video\\5320345492134524\\5.jpg,weibo-image-video\\5320345492134524\\6.jpg', '', 'https://weibo.com/1406511184/5320345492134524');
