INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5321017388965843', '山西全体育', '1406511184', '07月15日 18:54', '昨天，山西省委副书记、省长在太原理工大学调研时来到体育馆，与正在训练的教练员和队员亲切交流，向他们时隔14年第三次荣获CUBA总冠军表示祝贺，勉励大家发扬篮球拼搏精神，苦练本领、坚守热爱，在今后取得更多好成绩。希望学校坚持立德树人、体教融合，更好引领山西校园体育发展，在建设“双一流”高校上取得更大成效。CUBA超话#太原理工大学# \n                \n                                    在今晚刚刚结束的第28届CUBA男篮决赛中，太原理工大学队以71比65力克清华大学队，历史上第三次捧起总冠军奖杯，时隔14年再次登上最高领奖台。曹芷豪凭借23分、3篮板、2次助攻获得MVP。太原理工大学在两个校区设置大屏幕，为在校师生在周边群众提供了一个开心的夜宴。CUBA超话#太原理工大学# ​', '图片', 1, 3, 0, 'weibo-image-video\\5321017388965843\\1.jpg,weibo-image-video\\5321017388965843\\2.jpg,weibo-image-video\\5321017388965843\\3.jpg,weibo-image-video\\5321017388965843\\4.jpg,weibo-image-video\\5321017388965843\\5.jpg,weibo-image-video\\5321017388965843\\6.jpg,weibo-image-video\\5321017388965843\\7.jpg,weibo-image-video\\5321017388965843\\8.jpg,weibo-image-video\\5321017388965843\\9.jpg', '', 'https://weibo.com/1406511184/5321017388965843');
