INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5327529961589720', '山西新闻联播', '6213974274', '08月02日 18:13', '爱拼才会赢！2026年7月，太原理工大学男篮获得中国大学生篮球联赛总冠军，整个山西都跟着沸腾了。7月31日，主教练杨文海和队员们一起出席了“转型路上的奋进者”系列第七场记者见面会，分享夺冠背后的故事。#媒体原创##太原理工大学##男篮##CUBAL##冠军##山西##转型路上的奋进者##记者见面会##青春当燃不让##时代青年风采##原创##独家##记者采访#（制片人/张默 栾静 记者/王蕾 赵宇璇 黄晨轩 刘溢楠 武小虎 编辑/王蕾 郭振方 部分素材来源/@CUBAL @篮球摄手虎） L山西新闻联播的微博视频', '视频', 0, 0, 0, '', 'weibo-image-video\\5327529961589720\\video.mp4', 'https://weibo.com/6213974274/5327529961589720');
