INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5332574097375632', '幼稚园沐', '7146065429', '08月16日 16:16', '【200元悬赏求助寻找！】【感谢费200元！找到后联系我vx：shimukaoshi】您好哈，请问您可以帮忙找一位太原理工大学【航空工程专业】研究生学长学姐吗？会给您有【200元推荐费】属于航空航天学院辅导【航空工程专业】辅导科目【805力学基础】【26考研初试备考】😊有偿哈线上上课，时间灵活，今年年底初试前上完全部课程就好的。他们能辅导的话，会给你【200元】推荐费的。找到研究生后请联系我，谢谢。#太原理工大学#太原理工大学超话#太原理工大学考研#太原理工大学考研超话#太原理工大学研究生##太原理工大学研究生院#太原理工大学研究生超话', '图片', 0, 0, 0, 'weibo-image-video\\5332574097375632\\1.jpg', '', 'https://weibo.com/7146065429/5332574097375632');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5334144332857912', '有人管吗_', '7867262941', '08月21日 00:16', '为响应2026年全国大学生“三下乡”社会实践号召，6月28日至7月5日，太原理工大学青年研究中心“青研智行”实践队奔赴临汾市蒲县开展暑期“三下乡”社会实践。团队紧扣红军长征胜利90周年、人工智能科普、美育培育核心方向，以七彩假期特色课堂为主线，紧扣德智体美劳五育要求，融合红色故事宣讲、AI科普教学、创意美术辅导，扎根蒲县书香阵地，以青春微光助力县域科教振兴。@中青校媒   @qqqI_aM   @Thea-_-1   @belikeriver324  #青年眼中的三下乡#   、 #文明，让青春更美好##太原理工大学#', '图片', 0, 0, 0, 'weibo-image-video\\5334144332857912\\1.jpg,weibo-image-video\\5334144332857912\\2.jpg,weibo-image-video\\5334144332857912\\3.jpg,weibo-image-video\\5334144332857912\\4.jpg,weibo-image-video\\5334144332857912\\5.jpg,weibo-image-video\\5334144332857912\\6.jpg', '', 'https://weibo.com/7867262941/5334144332857912');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5334690999304587', '太原理工大学', '7461590254', '08月22日 12:28', '用一整年时光，记录太理的春夏秋冬春风群芳、盛夏烈阳、秋日落叶、冬雪飞檐。🌷🌊🍁❄️一帧帧光景，藏着属于太理的诗意与芬芳。愿你于匆匆求学路上，不忘抬头，共赏碧树斜阳。#太原理工大学#太原理工大学超话 L太原理工大学的微博视频 ​', '视频', 1, 1, 0, '', 'weibo-image-video\\5334690999304587\\video.mp4', 'https://weibo.com/7461590254/5334690999304587');
INSERT INTO `weibo_blogs` (`id`, `user_name`, `user_id`, `publish_time`, `content`, `form`, `share`, `comments`, `likes`, `image_paths`, `video_path`, `post_url`) VALUES ('5340804344186775', '中国教育新闻网', '1747774447', '09月08日 09:20', '【#太原理工大学#扎实推进以体育人 冠军奖杯背后的体育“必修课”】本报讯（记者 张商珉 通讯员 赵国俊）日前，太原理工大学男篮以71∶65力克清华大学，时隔14年再度站上中国大学生篮球联赛全国总冠军的领奖台。山西省人民政府专门发来贺信，把这支校园球队的拼搏荣光，化作三晋大地转型奋进的精神标杆。　　沉甸甸的冠军奖杯，背后是太原理工大学一套成熟完备的以体育人“操作系统”。在太原理工大学，体育不是特长生的“专属福利”，而是全体学生的“必修课”。该校开设体适能、武术、户外拓展、舞蹈等18门丰富多彩的体育课程，大一、大二学生体育必修学时不少于144学时。考核评价也一改过去期末“一考定分”的老路子，阳光长跑打卡、莱格尔体能测试、健康知识、运动技能、课外锻炼全部纳入过程性评价。　　“近3年，学校《国家学生体质健康标准》达标率稳定在95%以上。”太原理工大学体育与健康工程学院党委书记张体卫表示。从课程学习到日常练习再到赛事展示，一条闭环贯通的以体育人链条已经成型。　　体质弱的学生也不怕“掉队”。该校学生史航在本科入学时体重达115公斤，经过系统锻炼，一年之后体重降至92公斤。他的蜕变始于该校一次针对体质薄弱学生的运动干预，体育教师为他定制每周3次的快走加力量训练方案，配合饮食建议，坚持训练一年后，他不但成功减重，体测成绩也从“及格”跃升至“良好”。　　近年来，像史航这样体重超标、体质偏弱的学生并不鲜见。“以体育人不能只盯着运动能力强的学生，更要兜住体质薄弱学生的成长底线。”张体卫表示。为此，该校建立分层教学体系，对超重、肥胖和体质薄弱的学生实施精准干预；为身体存在特殊状况的学生单独开设保健课程；依托“太理体育阳光跑”小程序对定位、配速、数据统计和运动指导等实行数字化管理，体质健康测试结果与评奖评优、综合测评、荣誉评定相衔接，设立体质健康类荣誉，把课外锻炼纳入育人评价链条。　　2024年，该校体育与健康工程学院一项针对隐性肥胖大学生的综合干预研究显示，接受12周干预的实验组学生体重、BMI、体脂百分比均显著下降，学生心肺适能和体适能等指标显著改善。　　“体育不是教育的‘附加题’，而是‘必答题’。大家关注的不仅是一座奖杯，更是一所普通高校怎样在与顶尖大学的较量中找到自己的路。”太原理工大学党委书记沈兴全说。', '图片', 0, 0, 0, 'weibo-image-video\\5340804344186775\\1.jpg', '', 'https://weibo.com/1747774447/5340804344186775');
